const precOf=c=>c>=1000?1:c>=10?2:c>=1?3:c>=0.01?5:7;
const fmtP=(p,d)=>p==null||!isFinite(p)?'':(+p).toFixed(d);
const NOL={lastValueVisible:false,priceLineVisible:false,crosshairMarkerVisible:false};
/* ---------- indicator math ---------- */
const emaA=(a,p)=>{const k=2/(p+1);let e=null;return a.map(v=>v==null?(e):(e=e===null?v:v*k+e*(1-k)));};
const smaA=(a,p)=>a.map((_,i)=>{if(i<p-1)return null;let s=0;for(let j=i-p+1;j<=i;j++)s+=a[j];return s/p;});
const rsiA=(c,p)=>{const o=new Array(c.length).fill(null);if(c.length<p+2)return o;let g=0,l=0;for(let i=1;i<=p;i++){const d=c[i]-c[i-1];d>0?g+=d:l-=d;}g/=p;l/=p;o[p]=l===0?100:100-100/(1+g/l);for(let i=p+1;i<c.length;i++){const d=c[i]-c[i-1];g=(g*(p-1)+(d>0?d:0))/p;l=(l*(p-1)+(d<0?-d:0))/p;o[i]=l===0?100:100-100/(1+g/l);}return o;};
const atrA=(k,p)=>{const tr=k.map((x,i)=>i?Math.max(x.h-x.l,Math.abs(x.h-k[i-1].c),Math.abs(x.l-k[i-1].c)):x.h-x.l);let a=null;return tr.map((v,i)=>{if(i<p)return null;if(a===null){let s=0;for(let j=1;j<=p;j++)s+=tr[j];return a=s/p;}return a=(a*(p-1)+v)/p;});};
function adxA(k,p){const n=k.length,o=new Array(n).fill(null);if(n<2*p+2)return o;const tr=[],pd=[],md=[];for(let i=1;i<n;i++){const up=k[i].h-k[i-1].h,dn=k[i-1].l-k[i].l;pd.push(up>dn&&up>0?up:0);md.push(dn>up&&dn>0?dn:0);tr.push(Math.max(k[i].h-k[i].l,Math.abs(k[i].h-k[i-1].c),Math.abs(k[i].l-k[i-1].c)));}
 let st=0,sp=0,sm=0;for(let i=0;i<p;i++){st+=tr[i];sp+=pd[i];sm+=md[i];}const dx=[];for(let i=p;i<tr.length;i++){st=st-st/p+tr[i];sp=sp-sp/p+pd[i];sm=sm-sm/p+md[i];const a=100*sp/st,b=100*sm/st;dx.push(100*Math.abs(a-b)/((a+b)||1));}let a=null;for(let i=p-1;i<dx.length;i++){if(a===null){let s=0;for(let j=0;j<p;j++)s+=dx[j];a=s/p;}else a=(a*(p-1)+dx[i])/p;o[i+p+1]=a;}return o;}
function superA(k,p,m){const atr=atrA(k,p);const n=k.length,st=new Array(n).fill(null),dir=new Array(n).fill(1);let up=null,dn=null,d=1;for(let i=0;i<n;i++){if(atr[i]==null)continue;const hl2=(k[i].h+k[i].l)/2;let bu=hl2-m*atr[i],bd=hl2+m*atr[i];if(up!=null&&k[i-1].c>up)bu=Math.max(bu,up);if(dn!=null&&k[i-1].c<dn)bd=Math.min(bd,dn);if(up==null){up=bu;dn=bd;d=k[i].c>bd?1:-1;st[i]=d===1?up:dn;dir[i]=d;continue;}if(d===1&&k[i].c<up)d=-1;else if(d===-1&&k[i].c>dn)d=1;up=bu;dn=bd;st[i]=d===1?up:dn;dir[i]=d;}return {st,dir};}
const hlN=(k,a,b,f)=>{let m=f==='h'?-Infinity:Infinity;for(let j=Math.max(0,a);j<=b;j++){const v=k[j][f];if(f==='h'?v>m:v<m)m=v;}return isFinite(m)?m:null;};
