 EMA:{group:'trend',label:'EMA 20/50/200',pane:'main',params:{a:LEN(20,'EMA کوتاه','Fast EMA'),b:LEN(50,'EMA میانی','Mid EMA'),c:LEN(200,'EMA بلند','Slow EMA')},calc:(k,P)=>{const c=k.map(x=>x.c);return {e20:emaA(c,P.a),e50:emaA(c,P.b),e200:emaA(c,P.c)};},colors:{e20:'#f59e0b',e50:'#38bdf8',e200:'#a78bfa'},names:{e20:'EMA a',e50:'EMA b',e200:'EMA c'}},
 EMA9:{group:'trend',label:'EMA 9/21',pane:'main',params:{a:LEN(9,'EMA سریع','Fast EMA'),b:LEN(21,'EMA کند','Slow EMA')},calc:(k,P)=>{const c=k.map(x=>x.c);return {e9:emaA(c,P.a),e21:emaA(c,P.b)};},colors:{e9:'#fbbf24',e21:'#f472b6'}},
 SMA:{group:'trend',label:'SMA 50/150/200',pane:'main',params:{a:LEN(50,'SMA کوتاه','Fast SMA'),b:LEN(150,'SMA میانی','Mid SMA'),c:LEN(200,'SMA بلند','Slow SMA')},calc:(k,P)=>{const c=k.map(x=>x.c);return {s50:smaA(c,P.a),s150:smaA(c,P.b),s200:smaA(c,P.c)};},colors:{s50:'#10b981',s150:'#f97316',s200:'#ef4444'}},
 BOLL:{group:'vola',label:'Bollinger 20/2',pane:'main',params:{len:LEN(20),mult:N(2,0.5,5,0.1,'ضریب انحراف معیار','StdDev multiplier')},calc:(k,P)=>{const n=P.len,c=k.map(x=>x.c),m=smaA(c,n);const u=[],l=[];for(let i=0;i<c.length;i++){if(m[i]==null){u.push(null);l.push(null);continue;}let v=0;for(let j=i-n+1;j<=i;j++)v+=(c[j]-m[i])**2;const sd=Math.sqrt(v/n);u.push(m[i]+P.mult*sd);l.push(m[i]-P.mult*sd);}return {u,m,l};},colors:{u:'#64748b',m:'#94a3b8',l:'#64748b'},dash:{m:1},names:{u:'Upper',m:'Basis',l:'Lower'}},
 VWAP:{group:'trend',label:'VWAP (daily)',pane:'main',params:{src:{d:'hlc3',opts:['hlc3','close','ohlc4'],fa:'منبع قیمت','en':'Price source'}},calc:(k,P)=>{let pv=0,vv=0,day=null;return {vw:k.map(b=>{const d=new Date(b.t).getUTCDate();if(d!==day){day=d;pv=0;vv=0;}const tp=P.src==='close'?b.c:P.src==='ohlc4'?(b.o+b.h+b.l+b.c)/4:(b.h+b.l+b.c)/3;pv+=tp*(b.v||0);vv+=(b.v||0);return vv?pv/vv:null;})};},colors:{vw:'#e879f9'}},
 ST:{group:'trend',label:'Supertrend 10/3',pane:'main',params:{len:LEN(10,'طول ATR','ATR length'),mult:N(3,0.5,10,0.1,'ضریب ATR','ATR multiplier')},calc:(k,P)=>{const {st,dir}=superA(k,P.len,P.mult);return {up:st.map((v,i)=>dir[i]===1?v:null),dn:st.map((v,i)=>dir[i]===-1?v:null)};},colors:{up:GREEN,dn:RED},width:2,names:{up:'Up trend',dn:'Down trend'}},
 DON:{group:'vola',label:'Donchian 20',pane:'main',params:{len:LEN(20)},calc:(k,P)=>{const n=P.len;return {hh:k.map((_,i)=>i<n?null:hlN(k,i-n,i-1,'h')),ll:k.map((_,i)=>i<n?null:hlN(k,i-n,i-1,'l'))};},colors:{hh:'#60a5fa',ll:'#60a5fa'},dash:{hh:1,ll:1},names:{hh:'Upper',ll:'Lower'}},
