 MACD:{group:'mom',label:'MACD 12/26/9',pane:'sub',params:{f:LEN(12,'EMA سریع','Fast EMA'),s:LEN(26,'EMA کند','Slow EMA'),sig:LEN(9,'خط سیگنال','Signal length')},calc:(k,P)=>{const c=k.map(x=>x.c),f=emaA(c,P.f),s=emaA(c,P.s),w=P.s-1,m=f.map((v,i)=>i<w?null:v-s[i]),sg=emaA(m.map(v=>v==null?null:v),P.sig),w2=w+P.sig-1;return {h:m.map((v,i)=>v==null||sg[i]==null||i<w2?null:v-sg[i]),m,s:sg.map((v,i)=>i<w2?null:v)};},colors:{m:'#2962ff',s:'#f59e0b'},hist:'h',names:{m:'MACD',s:'Signal',h:'Histogram'}},
