 HMA:{group:'trend',label:'HMA 55',pane:'main',params:{len:LEN(55)},calc:(k,P)=>{const c=k.map(x=>x.c);const w=(a,p)=>a.map((_,i)=>{if(i<p-1)return null;let s=0,d=0;for(let j=0;j<p;j++){const v=a[i-j];if(v==null)return null;s+=v*(p-j);d+=p-j;}return s/d;});const n=P.len,h=Math.max(1,Math.round(n/2)),q=Math.max(1,Math.round(Math.sqrt(n)));const w1=w(c,h),w2=w(c,n);const diff=c.map((_,i)=>w1[i]==null||w2[i]==null?null:2*w1[i]-w2[i]);return {h:w(diff,q)};},colors:{h:'#e040fb'},width:2},
 WMA:{group:'trend',label:'WMA 20',pane:'main',params:{len:LEN(20)},calc:(k,P)=>{const c=k.map(x=>x.c),n=P.len;return {w:c.map((_,i)=>{if(i<n-1)return null;let s=0,d=0;for(let j=0;j<n;j++){s+=c[i-j]*(n-j);d+=n-j;}return s/d;})};},colors:{w:'#26c6da'}},
 SAR:{group:'trend',label:'Parabolic SAR',pane:'main',params:{step:N(0.02,0.001,0.2,0.001,'گام شتاب (AF)','Acceleration step'),max:N(0.2,0.02,1,0.01,'حداکثر شتاب','Max acceleration')},calc:(k,P)=>{const n=k.length,o=new Array(n).fill(null);if(n<3)return {s:o};const ST=P.step,MX=P.max;let up=k[1].c>k[0].c,af=ST,ep=up?k[0].h:k[0].l,sar=up?k[0].l:k[0].h;for(let i=1;i<n;i++){sar=sar+af*(ep-sar);if(up){sar=Math.min(sar,k[i-1].l,i>1?k[i-2].l:k[i-1].l);if(k[i].l<sar){up=false;sar=ep;ep=k[i].l;af=ST;}else if(k[i].h>ep){ep=k[i].h;af=Math.min(MX,af+ST);}}else{sar=Math.max(sar,k[i-1].h,i>1?k[i-2].h:k[i-1].h);if(k[i].h>sar){up=true;sar=ep;ep=k[i].h;af=ST;}else if(k[i].l<ep){ep=k[i].l;af=Math.min(MX,af+ST);}}o[i]=sar;}return {s:o};},colors:{s:'#2962ff'},dots:true},
 OBV:{group:'vol',label:'OBV',pane:'sub',calc:k=>{let o=0;return {o:k.map((b,i)=>{if(i)o+=b.c>k[i-1].c?(b.v||0):b.c<k[i-1].c?-(b.v||0):0;return o;})};},colors:{o:'#94a3b8'}},
 STOCH:{group:'mom',label:'Stochastic 14/3/3',pane:'sub',params:{k:LEN(14,'طول %K','%K length'),sm:LEN(3,'هموارسازی %K','%K smoothing'),d:LEN(3,'طول %D','%D length'),ob:N(80,50,100,1,'اشباع خرید','Overbought'),os:N(20,0,50,1,'اشباع فروش','Oversold')},calc:(k,P)=>{const n=P.k;const raw=k.map((b,i)=>{if(i<n-1)return null;const h=hlN(k,i-n+1,i,'h'),l=hlN(k,i-n+1,i,'l');return h===l?50:100*(b.c-l)/(h-l);});const w1=n-1+P.sm-1,kk=smaA(raw.map(v=>v==null?0:v),P.sm).map((v,i)=>i<w1?null:v);return {k:kk,d:smaA(kk.map(v=>v==null?0:v),P.d).map((v,i)=>i<w1+P.d-1?null:v)};},colors:{k:'#2962ff',d:'#ff6d00'},levels:[20,80],levelsOf:P=>[P.os,P.ob],names:{k:'%K',d:'%D'}},
 STOCHRSI:{group:'mom',label:'Stoch RSI 14',pane:'sub',params:{rsi:LEN(14,'طول RSI','RSI length'),st:LEN(14,'طول استوکاستیک','Stochastic length'),k:LEN(3,'هموارسازی %K','%K smoothing'),d:LEN(3,'طول %D','%D length')},calc:(k,P)=>{const r=rsiA(k.map(x=>x.c),P.rsi),n=P.st;const w0=P.rsi+n-1;const raw=r.map((v,i)=>{if(i<w0||v==null)return null;let h=-Infinity,l=Infinity;for(let j=i-n+1;j<=i;j++){if(r[j]==null)return null;h=Math.max(h,r[j]);l=Math.min(l,r[j]);}return h===l?50:100*(v-l)/(h-l);});const w1=w0+P.k-1,kk=smaA(raw.map(v=>v==null?0:v),P.k).map((v,i)=>i<w1?null:v);return {k:kk,d:smaA(kk.map(v=>v==null?0:v),P.d).map((v,i)=>i<w1+P.d-1?null:v)};},colors:{k:'#2962ff',d:'#ff6d00'},levels:[20,80],names:{k:'%K',d:'%D'}},
 CCI:{group:'mom',label:'CCI 20',pane:'sub',params:{len:LEN(20)},calc:(k,P)=>{const n=P.len,tp=k.map(b=>(b.h+b.l+b.c)/3),m=smaA(tp,n);return {c:tp.map((v,i)=>{if(m[i]==null)return null;let d=0;for(let j=i-n+1;j<=i;j++)d+=Math.abs(tp[j]-m[i]);d/=n;return d?(v-m[i])/(0.015*d):0;})};},colors:{c:'#ef6c00'},levels:[-100,100]},
 WPR:{group:'mom',label:'Williams %R 14',pane:'sub',params:{len:LEN(14)},calc:(k,P)=>{const n=P.len;return {w:k.map((b,i)=>{if(i<n-1)return null;const h=hlN(k,i-n+1,i,'h'),l=hlN(k,i-n+1,i,'l');return h===l?-50:-100*(h-b.c)/(h-l);})};},colors:{w:'#7e57c2'},levels:[-80,-20]},
 MFI:{group:'vol',label:'MFI 14',pane:'sub',params:{len:LEN(14)},calc:(k,P)=>{const n=P.len,tp=k.map(b=>(b.h+b.l+b.c)/3);return {m:k.map((b,i)=>{if(i<n)return null;let pos=0,neg=0;for(let j=i-n+1;j<=i;j++){const f=tp[j]*(k[j].v||0);if(tp[j]>tp[j-1])pos+=f;else if(tp[j]<tp[j-1])neg+=f;}return neg===0?100:100-100/(1+pos/neg);})};},colors:{m:'#26a69a'},levels:[20,80]},
