function saveDrawings(H,force){try{const mine=H.draw.filter(d=>d.points&&d.points.length).map(d=>({name:d.name,points:d.points.map(p=>({timestamp:p.timestamp,value:p.value})),styles:d.styles&&Object.keys(d.styles).length?Object.assign({},d.styles,{line:{color:d.styles.color,size:d.styles.size,style:d.styles.dash?'dashed':'solid'}}):undefined,extendData:typeof d.extendData==='string'?d.extendData:undefined,lock:true,ulock:d.lock||undefined,hidden:d.hidden||undefined}));
 const j=JSON.stringify(mine);if(force||j!==H._dlast){H._dlast=j;if(mine.length)localStorage.setItem(dkey(H),j);else localStorage.removeItem(dkey(H));}}catch(e){}}
